import{_ as r,c as o,o as t,a5 as l}from"./chunks/framework.DuCYAsAJ.js";const f=JSON.parse('{"title":"基础设施与部署","description":"","frontmatter":{"title":"基础设施与部署","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#9","branch":"main","level":0,"order":9,"date":"2026-05-24T00:00:00.000Z"},"headers":[],"relativePath":"posts/projects/zfeed/09-infrastructure-and-deployment/index.md","filePath":"posts/projects/zfeed/09-infrastructure-and-deployment/index.md","lastUpdated":1779632679000}'),a={name:"posts/projects/zfeed/09-infrastructure-and-deployment/index.md"};function c(d,e,i,b,n,p){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="基础设施与部署" tabindex="-1">基础设施与部署 <a class="header-anchor" href="#基础设施与部署" aria-label="Permalink to &quot;基础设施与部署&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1" target="_blank" rel="noreferrer">README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/build/content-rpc.Dockerfile" target="_blank" rel="noreferrer">build/content-rpc.Dockerfile</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/build/count-rpc.Dockerfile" target="_blank" rel="noreferrer">build/count-rpc.Dockerfile</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/build/front-api.Dockerfile" target="_blank" rel="noreferrer">build/front-api.Dockerfile</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/build/interaction-rpc.Dockerfile" target="_blank" rel="noreferrer">build/interaction-rpc.Dockerfile</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/build/search-rpc.Dockerfile" target="_blank" rel="noreferrer">build/search-rpc.Dockerfile</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/build/user-rpc.Dockerfile" target="_blank" rel="noreferrer">build/user-rpc.Dockerfile</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/README.md?plain=1" target="_blank" rel="noreferrer">deploy/README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml" target="_blank" rel="noreferrer">deploy/docker-compose.yml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf" target="_blank" rel="noreferrer">deploy/nginx/default.conf</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/prometheus/prometheus.yml" target="_blank" rel="noreferrer">deploy/prometheus/prometheus.yml</a></li></ul></details><p>本页从高层介绍 <code>zfeed</code> 的基础设施栈、部署编排，以及支撑微服务生态的运维组件。系统设计为完全容器化且可观测，使用现代云原生栈来处理消息通信、服务发现和数据一致性。</p><h2 id="部署栈与编排" tabindex="-1">部署栈与编排 <a class="header-anchor" href="#部署栈与编排" aria-label="Permalink to &quot;部署栈与编排&quot;">​</a></h2><p>整个 <code>zfeed</code> 环境使用 Docker Compose 编排，负责管理 6 个后端服务及其支撑基础设施的生命周期。该栈设计为通过统一启动脚本完成一键部署 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/scripts/start.sh#L14-L17" target="_blank" rel="noreferrer">scripts/start.sh#14-17</a></p><h3 id="服务拓扑" tabindex="-1">服务拓扑 <a class="header-anchor" href="#服务拓扑" aria-label="Permalink to &quot;服务拓扑&quot;">​</a></h3><p>部署被划分为三个逻辑层：</p><ol><li>网关层：Nginx 作为反向代理，处理 SSL 终止（可选）和 request ID 注入 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf#L1-L4" target="_blank" rel="noreferrer">deploy/nginx/default.conf#1-4</a>，并将流量转发到 <code>front-api</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf#L57-L70" target="_blank" rel="noreferrer">deploy/nginx/default.conf#57-70</a></li><li>应用层：6 个基于 go-zero 的服务（<code>front-api</code>、<code>user-rpc</code>、<code>content-rpc</code>、<code>interaction-rpc</code>、<code>count-rpc</code>、<code>search-rpc</code>）运行在隔离容器中 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L1-L36" target="_blank" rel="noreferrer">deploy/docker-compose.yml#1-36</a></li><li>基础设施层：包含 MySQL、Redis、Kafka、Etcd 和 Canal 等状态与协调服务 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L40-L150" target="_blank" rel="noreferrer">deploy/docker-compose.yml#40-150</a></li></ol><h3 id="基础设施组件图" tabindex="-1">基础设施组件图 <a class="header-anchor" href="#基础设施组件图" aria-label="Permalink to &quot;基础设施组件图&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>在 zfeed 中的角色</th><th>端口（内部）</th></tr></thead><tbody><tr><td>Etcd</td><td>服务发现与配置管理 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L40-L69" target="_blank" rel="noreferrer">deploy/docker-compose.yml#40-69</a></td><td><code>2379</code></td></tr><tr><td>MySQL</td><td>所有领域的主要持久化存储 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L80-L110" target="_blank" rel="noreferrer">deploy/docker-compose.yml#80-110</a></td><td><code>3306</code></td></tr><tr><td>Redis</td><td>会话存储、Feed 快照和高速缓存 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L71-L78" target="_blank" rel="noreferrer">deploy/docker-compose.yml#71-78</a></td><td><code>6379</code></td></tr><tr><td>Kafka</td><td>互动事件与计数更新的事件总线 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L112-L131" target="_blank" rel="noreferrer">deploy/docker-compose.yml#112-131</a></td><td><code>9092</code></td></tr><tr><td>Canal</td><td>将 MySQL binlog 中的 CDC（Change Data Capture）变更同步到 Kafka <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L133-L150" target="_blank" rel="noreferrer">deploy/docker-compose.yml#133-150</a></td><td><code>11111</code></td></tr><tr><td>XXL-Job</td><td>用于热门 Feed 排序的分布式任务调度 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L152-L165" target="_blank" rel="noreferrer">deploy/docker-compose.yml#152-165</a></td><td><code>8080</code></td></tr></tbody></table><p>来源：</p><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L1-L165" target="_blank" rel="noreferrer">deploy/docker-compose.yml#1-165</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/README.md?plain=1#L19-L25" target="_blank" rel="noreferrer">deploy/README.md#19-25</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L23-L30" target="_blank" rel="noreferrer">README.md#23-30</a></li></ul><h2 id="nginx-网关与请求路由" tabindex="-1">Nginx 网关与请求路由 <a class="header-anchor" href="#nginx-网关与请求路由" aria-label="Permalink to &quot;Nginx 网关与请求路由&quot;">​</a></h2><p>Nginx 作为统一入口 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/README.md?plain=1#L5-L5" target="_blank" rel="noreferrer">deploy/README.md#5</a>。它执行 JSON 格式的访问日志记录并传播追踪信息 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf#L6-L21" target="_blank" rel="noreferrer">deploy/nginx/default.conf#6-21</a>，同时将所有 <code>/v1/</code> 流量路由到 <code>front-api</code> 服务 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf#L57-L70" target="_blank" rel="noreferrer">deploy/nginx/default.conf#57-70</a></p><p>部署流程图：该图将 <code>docker-compose.yml</code> 中定义的物理基础设施组件映射到一次请求的逻辑流。</p><p>来源：</p><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf#L23-L70" target="_blank" rel="noreferrer">deploy/nginx/default.conf#23-70</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L2-L38" target="_blank" rel="noreferrer">deploy/docker-compose.yml#2-38</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L23-L30" target="_blank" rel="noreferrer">README.md#23-30</a></li></ul><h2 id="数据库与-schema-管理" tabindex="-1">数据库与 Schema 管理 <a class="header-anchor" href="#数据库与-schema-管理" aria-label="Permalink to &quot;数据库与 Schema 管理&quot;">​</a></h2><p><code>zfeed</code> 使用 MySQL 作为事实来源。Schema 管理通过 <code>scripts/sql/</code> 中的 SQL 脚本完成 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L93-L93" target="_blank" rel="noreferrer">deploy/docker-compose.yml#93</a>，这些脚本会在容器初始化期间通过自定义 reseed 脚本自动应用 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L95-L95" target="_blank" rel="noreferrer">deploy/docker-compose.yml#95</a></p><p>系统使用多个领域专属表，例如 <code>zfeed_user</code>、<code>zfeed_content</code> 和 <code>zfeed_count_value</code>。可靠事件投递则通过 <code>zfeed_like_event_outbox</code> 等 outbox 表管理。</p><p>表结构和索引详情请参见 <a href="./01-database-schema-and-migrations.html">数据库 Schema 与迁移</a>。</p><p>来源：</p><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L80-L110" target="_blank" rel="noreferrer">deploy/docker-compose.yml#80-110</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L94-L107" target="_blank" rel="noreferrer">README.md#94-107</a></li></ul><h2 id="可观测性流水线" tabindex="-1">可观测性流水线 <a class="header-anchor" href="#可观测性流水线" aria-label="Permalink to &quot;可观测性流水线&quot;">​</a></h2><p>可观测性栈通过三大支柱深入呈现系统健康状况：</p><ol><li>指标：Prometheus 抓取每个服务的 exporter 端口，例如 <code>9290</code> 到 <code>9295</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/prometheus/prometheus.yml#L9-L37" target="_blank" rel="noreferrer">deploy/prometheus/prometheus.yml#9-37</a></li><li>追踪：OpenTelemetry（OTEL）collector 将 trace 转发到 Jaeger，用于分布式请求可视化 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L167-L189" target="_blank" rel="noreferrer">deploy/docker-compose.yml#167-189</a></li><li>日志：go-zero 生成结构化日志，包括 access、error、slow、stat，可通过 Filebeat/Logstash 流水线收集 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L59-L62" target="_blank" rel="noreferrer">README.md#59-62</a></li></ol><p>指标与追踪配置详情请参见 <a href="./02-observability-metrics-tracing-and-logging.html">可观测性：指标、追踪与日志</a>。</p><p>来源：</p><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/prometheus/prometheus.yml#L1-L38" target="_blank" rel="noreferrer">deploy/prometheus/prometheus.yml#1-38</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L167-L189" target="_blank" rel="noreferrer">deploy/docker-compose.yml#167-189</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L57-L62" target="_blank" rel="noreferrer">README.md#57-62</a></li></ul><h2 id="cdc-与消息基础设施" tabindex="-1">CDC 与消息基础设施 <a class="header-anchor" href="#cdc-与消息基础设施" aria-label="Permalink to &quot;CDC 与消息基础设施&quot;">​</a></h2><p>为了将高频计数和社交互动与核心业务逻辑解耦，<code>zfeed</code> 使用 Change Data Capture（CDC）。Canal 监听 MySQL binlog 并将变更流式写入 Kafka <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L133-L150" target="_blank" rel="noreferrer">deploy/docker-compose.yml#133-150</a>。这使 <code>count-rpc</code> 服务可以异步更新计数器，而不会影响主要写操作的延迟。</p><p>Canal 到 Kafka 的流水线以及 Transactional Outbox 模式详情，请参见 <a href="./03-canal-cdc-and-kafka-messaging.html">Canal CDC 与 Kafka 消息</a>。</p><p>CDC 实体关联图：该图连接了负责跨基础设施组件移动数据的代码实体。</p><p>来源：</p><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L112-L150" target="_blank" rel="noreferrer">deploy/docker-compose.yml#112-150</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L29-L30" target="_blank" rel="noreferrer">README.md#29-30</a></li></ul><h2 id="子页面" tabindex="-1">子页面 <a class="header-anchor" href="#子页面" aria-label="Permalink to &quot;子页面&quot;">​</a></h2><ul><li><a href="./01-database-schema-and-migrations.html">数据库 Schema 与迁移</a>：MySQL 表、索引和迁移策略的详细视图。</li><li><a href="./02-observability-metrics-tracing-and-logging.html">可观测性：指标、追踪与日志</a>：Prometheus、Jaeger 与日志流水线的配置和用法。</li><li><a href="./03-canal-cdc-and-kafka-messaging.html">Canal CDC 与 Kafka 消息</a>：事件驱动架构和 CDC 流程的技术实现。</li></ul>',37)])])}const m=r(a,[["render",c]]);export{f as __pageData,m as default};
